values = [10, 2, 1, 33, 17, 64, 9, 1 << 62, -5, 2**70, 3.5, True]
print({10, 2, 1}, {3, 100, 7, 8, 5, 1}, {16, 0, 1, 2, 3, 48, 32})
print(set(values), {value for value in values})
grown = set()
for value in [200, 8, 16, 24, 1, 9, 72, 136]:
    grown.add(value)
print(grown, list(grown), sorted(grown))
x = 5
print({x, 3, 13}, frozenset([13, 3, 5, 21]))
print([hash(value) for value in [-1, 1 << 62, 2**70, -(2**70), 1.5, -2.25, 1e300, None]])
print(hash((1, 2)), hash(()), hash((None, 1.5, (3,))))
print({(1, 2), (2, 1), (0, 0)}, {1.5, 2, 3.0, 0.25})
